# Efficient solution
def solve(data):
    label = data["label"]
    if label == "":
        return 0
    elif label == "A":
        return 1
    elif label == "Z":
        return 26
    elif label == "AA":
        return 27
    else:
        # Calculate the column number using the formula: 26^i * j + k
        i = len(label) - 1
        j = ord(label[i]) - ord('A')
        k = 0
        for c in label[:-1]:
            k = k * 26 + ord(c) - ord('A')
        return k + 1 + j * 26 ** i

